    id: 'rl-damping-is-actually-applied',
    why: '阻尼 `correction ** damping` 压的是噪声放大。不施加 ⇒ 每一轮的修正量按原样乘上去，30 轮之后一张有噪声的图会被反卷积「锐化」成一堆尖刺，而 `iterations_used` 与形状一个字都不变',
