    id: 'npgrid-argsort-desc-takes-the-largest',
    why: '`np.argsort(v)[::-1]` 取的是**最大**的那几个。不翻 ⇒ `_hist_modes` 的 `max_levels` 留下的是 prominence 最小的几个峰',
