    why: '低梯度样本不足 100 个就退回整帧 —— 一个百分位在几十个样本上没有意义。不退 ⇒ 小帧上的层结构由十几个像素决定',
    file: `${V}/seg-scale-adaptive.ts`,
    find: '  if (sel.length < MIN_SEL_SIZE) sel = Array.from(coarse.data)',
    replace: '  if (sel.length < 0) sel = Array.from(coarse.data)',
